import '../../../src/quill.js';
import { describe, expect, test, vitest, beforeEach } from 'vitest';
import createRegistryWithFormats from '../../../src/core/utils/createRegistryWithFormats.js';
import Quill, { globalRegistry, expandConfig } from '../../../src/core/quill.js';
import * as Parchment from 'parchment';

// Create a minimal debug mock
function createDebugMock() {
  const errors: string[] = [];
  const error = (message: string) => errors.push(message);
  return { error, errors };
}

// Helper to query for blots by name - use BLOT scope to get proper matches
function queryBlot(registry: Parchment.Registry, name: string) {
  return registry.query(name, Parchment.Scope.BLOT);
}

describe('createRegistryWithFormats', () => {
  beforeEach(() => {
    // Clear any previous registrations that might interfere
    // We always pass globalRegistry as source, which has everything registered
  });

  test('returns a new Registry', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats([], globalRegistry, debug);
    expect(registry).toBeInstanceOf(Parchment.Registry);
    // Should not be the same instance
    expect(registry).not.toBe(globalRegistry);
  });

  test('always includes core blots', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats([], globalRegistry, debug);

    for (const blotName of ['block', 'break', 'cursor', 'inline', 'scroll', 'text']) {
      const result = queryBlot(registry, blotName);
      expect(result).toBeTruthy();
    }
  });

  test('includes specified formats', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['bold'], globalRegistry, debug);

    const bold = queryBlot(registry, 'bold');
    expect(bold).toBeTruthy();
  });

  test('includes list and its required container (list-container)', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['list'], globalRegistry, debug);

    const list = queryBlot(registry, 'list');
    expect(list).toBeTruthy();

    const listContainer = queryBlot(registry, 'list-container');
    expect(listContainer).toBeTruthy();
  });

  test('includes code-block and its required container (code-block-container)', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['code-block'], globalRegistry, debug);

    const codeBlock = queryBlot(registry, 'code-block');
    expect(codeBlock).toBeTruthy();

    const codeBlockContainer = queryBlot(registry, 'code-block-container');
    expect(codeBlockContainer).toBeTruthy();
  });

  test('skips unknown format names and reports error', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['nonexistent-format'], globalRegistry, debug);

    // Should still have core blots
    const scroll = queryBlot(registry, 'scroll');
    expect(scroll).toBeTruthy();

    // Unknown format should not be in registry
    const missing = queryBlot(registry, 'nonexistent-format');
    expect(missing).toBeNull();

    // Error should be reported
    expect(debug.errors.length).toBe(1);
    expect(debug.errors[0]).toContain('nonexistent-format');
  });

  test('reports error for each unknown format', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['nonexistent1', 'nonexistent2'], globalRegistry, debug);

    expect(debug.errors.length).toBe(2);
    expect(debug.errors[0]).toContain('nonexistent1');
    expect(debug.errors[1]).toContain('nonexistent2');
  });

  test('mixes known and unknown formats', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['bold', 'fake-format', 'italic'], globalRegistry, debug);

    expect(queryBlot(registry, 'bold')).toBeTruthy();
    expect(queryBlot(registry, 'italic')).toBeTruthy();
    expect(queryBlot(registry, 'fake-format')).toBeNull();
    expect(debug.errors.length).toBe(1);
    expect(debug.errors[0]).toContain('fake-format');
  });

  test('multiple known formats work together', () => {
    const debug = createDebugMock();
    const registry = createRegistryWithFormats(['bold', 'italic', 'underline'], globalRegistry, debug);

    expect(queryBlot(registry, 'bold')).toBeTruthy();
    expect(queryBlot(registry, 'italic')).toBeTruthy();
    expect(queryBlot(registry, 'underline')).toBeTruthy();
    expect(debug.errors.length).toBe(0);
  });

  test('cycle detection in required containers', () => {
    // Create a mock setup where we test cycle detection
    // We need to simulate a cycle by creating a custom blot that requires itself

    // Since we can't easily inject a cycle through globalRegistry,
    // let's test via the helper by checking that the function doesn't hang
    const debug = createDebugMock();

    // Create a registry with a cycle: A requires B requires A
    const testRegistry = new Parchment.Registry();

    // We can't directly create this cycle in the registry easily,
    // but we can test that normal usage doesn't cause issues
    // The cycle test is more about not hanging
    // Let's verify the function returns promptly for normal usage
    const startTime = Date.now();
    createRegistryWithFormats(['bold', 'italic', 'link'], globalRegistry, debug);
    const elapsed = Date.now() - startTime;

    expect(elapsed).toBeLessThan(1000); // Should complete quickly
    expect(debug.errors.length).toBe(0);
  });
});

describe('expandConfig with formats option', () => {
  test('formats option works through expandConfig', () => {
    const container = document.createElement('div');
    document.body.appendChild(container);

    const config = expandConfig(container, {
      formats: ['bold', 'italic'],
    });

    // Should contain core blots and the specified formats
    expect(queryBlot(config.registry, 'scroll')).toBeTruthy();
    expect(queryBlot(config.registry, 'block')).toBeTruthy();
    expect(queryBlot(config.registry, 'bold')).toBeTruthy();
    expect(queryBlot(config.registry, 'italic')).toBeTruthy();

    // Should NOT contain formats not specified
    expect(queryBlot(config.registry, 'header')).toBeNull();
    expect(queryBlot(config.registry, 'list')).toBeNull();

    document.body.removeChild(container);
  });

  test('formats option includes required containers', () => {
    const container = document.createElement('div');
    document.body.appendChild(container);

    const config = expandConfig(container, {
      formats: ['list'],
    });

    // list format and its required container should both be present
    expect(queryBlot(config.registry, 'list')).toBeTruthy();
    expect(queryBlot(config.registry, 'list-container')).toBeTruthy();

    // Core blots should be present
    expect(queryBlot(config.registry, 'scroll')).toBeTruthy();

    // header should NOT be present
    expect(queryBlot(config.registry, 'header')).toBeNull();

    document.body.removeChild(container);
  });

  test('formats null uses global registry', () => {
    const container = document.createElement('div');
    document.body.appendChild(container);

    const config = expandConfig(container, {
      formats: null,
    });

    // Should use global registry (which has everything)
    expect(queryBlot(config.registry, 'header')).toBeTruthy();
    expect(queryBlot(config.registry, 'bold')).toBeTruthy();

    document.body.removeChild(container);
  });

  test('no formats option uses global registry', () => {
    const container = document.createElement('div');
    document.body.appendChild(container);

    const config = expandConfig(container, {});

    // Should use global registry
    expect(queryBlot(config.registry, 'header')).toBeTruthy();
    expect(queryBlot(config.registry, 'bold')).toBeTruthy();

    document.body.removeChild(container);
  });

  test('explicit registry takes precedence over formats', () => {
    const container = document.createElement('div');
    document.body.appendChild(container);

    const customRegistry = new Parchment.Registry();
    customRegistry.register(Quill.import('blots/scroll'));
    customRegistry.register(Quill.import('formats/header'));

    const config = expandConfig(container, {
      formats: ['bold'],
      registry: customRegistry,
    });

    // Should use the explicit registry
    expect(config.registry).toBe(customRegistry);
    expect(queryBlot(config.registry, 'bold')).toBeNull();
    expect(queryBlot(config.registry, 'header')).toBeTruthy();

    document.body.removeChild(container);
  });
});

